import { describeApi, readEndpoints, writeEndpoints } from "./api-endpoints.ts";

/** Registry-derived request index, not a substitute for nested types and semantic contracts. */
export function renderApiReference(): string {
  const capabilities = describeApi();
  const lines = [
    "# HTTP API endpoint reference",
    "",
    "Generated by `npm run api:reference` from the endpoint definitions. Do not edit by hand.",
    "",
    `API: \`${capabilities.api}\`. Contract version: **${capabilities.contractVersion}** (independent of project schema and database format).`,
    "",
    "See the [developer reference](developer-reference.md#headless-http-operation) for connection, errors, trusted provenance and recovery. This index lists wire query parameters and accepted top-level JSON keys. Nested payload/response types derive from the same definitions through the typed client; semantic guards and per-query bounds remain documented in their owning guides.",
    "",
    `Features: ${capabilities.features.map((feature) => "`" + feature + "`").join(", ")}.`,
    "",
    "<!-- prettier-ignore -->",
    "| Limit | Maximum |",
    "| --- | --- |",
    ...Object.entries(capabilities.limits).map(([name, value]) => `| ${name} | ${value} |`),
    "",
    "GET query parameters below mark required values with `*`. Encodings: text, canonical safe integer, CSV list, or JSON. Unknown/duplicate query keys reject; endpoints with no parameters accept no filters. POST accepts a JSON object; unknown keys reject. Every POST requires the local session token, matching Origin and selected-project context. Limits here are a supported subset, not a complete catalogue of application bounds.",
    "",
    "<!-- prettier-ignore -->",
    "| Method | Path | Query parameters or JSON keys |",
    "| --- | --- | --- |",
  ];
  for (const path of Object.keys(readEndpoints).sort()) {
    const endpoint = readEndpoints[path as keyof typeof readEndpoints];
    const parameters = endpoint.query.parameters
      .map((field) => `\`${field.name}\`${field.required ? "*" : ""} (${field.encoding})`)
      .join(", ");
    lines.push(`| GET | \`${path}\` | ${parameters || "—"} |`);
  }
  for (const path of Object.keys(writeEndpoints).sort()) {
    const endpoint = writeEndpoints[path as keyof typeof writeEndpoints];
    lines.push(
      `| POST | \`${path}\` | ${endpoint.inputKeys.map((key) => "`" + key + "`").join(", ")} |`,
    );
  }
  return lines.join("\n") + "\n";
}
